import{c as a,Q as l,j as o,m as e}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"仓库风格","description":"","frontmatter":{"title":"仓库风格"},"headers":[],"relativePath":"综合知识/架构设计/仓库风格.md","filePath":"综合知识/架构设计/仓库风格.md","lastUpdated":null}'),r={name:"综合知识/架构设计/仓库风格.md"};function i(n,t,s,d,h,u){return l(),o("div",null,[...t[0]||(t[0]=[e('<blockquote><p>仓库风格的核心：以<strong>数据为中心</strong>，所有操作围绕中央数据结构展开。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 数据库系统：中央共享数据源 + 独立处理单元</li><li>[ ] 黑板系统：知识源 + 黑板 + 控制（无确定性算法场景）</li><li>[ ] 超文本系统：网状链接</li><li>[ ] 仓库 vs 黑板共同点（都有中央数据结构）</li><li>[ ] 现代 IDE → 数据仓储</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="数据库系统" tabindex="-1">数据库系统 <a class="header-anchor" href="#数据库系统" aria-label="Permalink to &quot;数据库系统&quot;">​</a></h3><ul><li>构件 = <strong>中央共享数据源</strong> + 多个<strong>独立处理单元</strong></li><li>构件分两类：中央数据结构（注册表）说明当前状态 + 独立处理单元在中央数据上执行操作</li><li>⚠️ &quot;控制模块&quot;不属于仓库风格主要构件</li></ul><h3 id="黑板系统-高频考点" tabindex="-1">黑板系统（高频考点） <a class="header-anchor" href="#黑板系统-高频考点" aria-label="Permalink to &quot;黑板系统（高频考点）&quot;">​</a></h3><p><strong>三大构件：</strong></p><ol><li><strong>知识源</strong> — 监听黑板状态变化，条件满足时被触发执行</li><li><strong>黑板</strong>（全局数据库）— 存储解空间状态</li><li><strong>控制</strong> — 完全由<strong>黑板的状态驱动</strong></li></ol><p><strong>适用领域：</strong></p><ul><li>语音识别、信号处理</li><li>问题规划、编译器优化</li><li>问题复杂、解空间很大、求解过程不确定的软件系统</li></ul><blockquote><p>⚠️ 现代编译器的 IDE 环境采用<strong>数据仓储</strong>（以数据为中心的架构风格），中心数据 = 程序的语法树。</p></blockquote><h3 id="超文本系统" tabindex="-1">超文本系统 <a class="header-anchor" href="#超文本系统" aria-label="Permalink to &quot;超文本系统&quot;">​</a></h3><ul><li>网状链接，用户可按联想跳转</li><li>多用于互联网</li></ul><h3 id="🎯-仓库与黑板共同点" tabindex="-1">🎯 仓库与黑板共同点 <a class="header-anchor" href="#🎯-仓库与黑板共同点" aria-label="Permalink to &quot;🎯 仓库与黑板共同点&quot;">​</a></h3><blockquote><p>都有一个<strong>中央数据结构</strong>（核心共同特征）</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>中央数据</th><th>处理单元</th></tr></thead><tbody><tr><td>数据库</td><td>中央共享数据源</td><td>独立处理单元</td></tr><tr><td>黑板</td><td>黑板（全局数据库）</td><td>知识源</td></tr></tbody></table><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>参见 <a href="./.html">架构师-备考 综合知识-架构设计-架构风格与模式#练习题</a>（Q4, Q7, Q15, Q27, Q36, Q39, Q41, Q51, Q52, Q53, Q54, Q67, Q69, Q74 等）</p>',19)])])}const p=a(r,[["render",i]]);export{b as __pageData,p as default};
